  }

  printf("\nMatrix1 + Matrix2 = \n");
  for (int i = 0; i < 2; i++) {
    printf("%d %d",mat1[i][0] + mat2[i][0], mat1[i][1] + mat2[i][1]);
    printf("\n");
  }
}
