void        draw_cube(int x, int y)
{
    int i;
    int j;

    i = x;
    j = y;
    while (j < g_tile_size + y)
    {
        while (i < g_tile_size + x)
        {
            my_mlx_pixel_put(&g_image, j, i, 0xFF0000);
            i++;
        }
        i = x;
        j++;
    }
}

void        norm_it(char **meh)
{
    int e;
    int f;
    int x;
    int y;

    e = 0;
    f = 0;
    x = 0;
    y = 0;
    while (meh[e])
    {
        while (meh[e][f])
        {
            if (meh[e][f] == '1')
                draw_cube(y, x);
            f++;
            x = x + g_tile_size;
        }
        f = 0;
        e++;
        x = 0;
        y = y + g_tile_size;
    }
}

