typedef struct q{
    int coeff;
    int pow;
    struct q* next;
}node;
void createNode(int c, int p, node** exp)
{
    if(c==0)
        return;
    node* x=*exp;
    while(x)
    {
        if(x->pow == p)
        {
            if(x->coeff < 0 && c < 0)
                x->coeff=-(x->coeff+c);
            else
                x->coeff=x->coeff+c;
            return;
        }
        x=x->next;
    }
    node* ret=(node*) malloc(sizeof(node));
    ret->coeff=c;
    ret->pow=p;
    if(*exp==NULL)
    {
        ret->next=*exp;
        *exp=ret;
    }
    else
    {
            if(p > (*exp)->pow)
            {
                ret->next=*exp;
                *exp=ret;
            }
            else
            {
                x=*exp;
                while(x->next!=NULL && x->next->pow > p)
                    x=x->next;
                ret->next=x->next;
                x->next=ret;
            }
    }
}
node* poly_add_sub(char task, node* exp1, node* exp2)
{
    node* res=NULL;
    while(exp1 || exp2)
    {
        if(!exp2)
        {
            createNode(exp1->coeff,exp1->pow,&res);
            exp1=exp1->next;
        }
        else if(!exp1)
        {
            if(task=='+')
                createNode(exp2->coeff,exp2->pow,&res);
            else
            createNode(-(exp2->coeff),exp2->pow,&res);
            exp2=exp2->next;
        }
        else if(exp1->pow > exp2->pow)
        {
            createNode(exp1->coeff,exp1->pow,&res);
            exp1=exp1->next;
        }
        else if(exp1->pow < exp2->pow)
        {
            if(task=='+')
                createNode(exp2->coeff,exp2->pow,&res);
            else
                createNode(-(exp2->coeff),exp2->pow,&res);
            exp2=exp2->next;
        }
        else if(exp1->pow == exp2->pow )
        {
            if(task=='+' && (exp1->coeff + exp2->coeff)!=0)
                createNode(exp1->coeff+exp2->coeff,exp1->pow,&res);
            else if(task=='-' && (exp1->coeff - exp2->coeff)!=0)
                createNode(exp1->coeff-exp2->coeff,exp1->pow,&res);
            exp1=exp1->next;
            exp2=exp2->next;
        }
    }
    return res;
}
node* poly_mul(node* exp1, node* exp2)
{
    node* res=NULL;
    node* t=exp2;
    while(exp1)
    {
        while(t)
        {
            createNode(exp1->coeff * t->coeff,exp1->pow + t->pow,&res);
            t=t->next;
        }
        t=exp2;
        exp1=exp1->next;
    }
    return res;
}
void display(node* res)
{
    int f=0;
    while(res)
    {
        if(res->coeff>0)
        {
            if(f==0)
                printf(" %dx^%d ",res->coeff,res->pow);
            else
                printf("+ %dx^%d ",res->coeff,res->pow);
        }
        else if(res->coeff<0)
            printf("- %dx^%d ",-res->coeff,res->pow);
        f=1;
        res=res->next;
    }
}
