typedef int BOOL;

# define TRUE 1

#define FALSE 0

BOOL CheckBit(int iNo)
{
    int iMask = 0X00000E00;

    int iResult = 0;
    if(iNo < 0)
    {
        iNo = -iNo;
    }
    iResult = iNo & iMask;

    if(iResult == iMask)
    {
        return TRUE;
    }
    else
    {
        return FALSE;
    }
}
