    BOOL bRet = FALSE;

    printf("Enter number\n");
    scanf("%d",&iNo);

    bRet = CheckBit(iNo);
    if(bRet == TRUE)
    {
        printf("6th,7th and 12th bit is on\n");
    }
    else
    {
        printf("One of the bit or all bits are Off\n");
    }
    return 0;
}




