int main(void){
    int count = 0, total_len = 0;
    int chars = 0, times = 0;

    while(input[count] != '\0'){

        if(input[count] == '('){
            count++;


            while(input[count] != 'x'){
                chars = chars * 10 + (input[count] - '0'); 
                count++;
            }
                count++;


            while(input[count] != ')'){
                times = times * 10 + (input[count] - '0'); 
                count++;
            }

            total_len = total_len + (chars * times); 
            count = count + chars;  

            chars = 0; 
            times = 0;
        }
        else{
            total_len++;
        }

        count++;
    }

    printf("answer=%d\n", total_len);


    return EXIT_SUCCESS;
}
