int     ft_is_prime(int nb)
{
    int i;

    i = 2;
    while (i < nb)
    {
        if (nb % i == 0)
            return (0);
        i++;
    }
    return (1);
}

int     ft_add_prime_sum(int nb)
{
    int     i;
    int     sum;

    i = 2;
    sum = 0;
        if (nb <= 0)
            return (0);
    while (i <= nb)
    {
        if (ft_is_prime(i))
            sum += i;
        i++;
    }
    return (sum);
}

