    struct node* link;
};
struct node* root = NULL;


int main()
{
    int choice, value;
    while(1)
    {
        printf("Single Linked List Operations : \n");
        printf("1. Add at End\n");
        printf("2. Add at Begin\n");
        printf("3. Add at After\n");
        printf("4. Display\n");
        printf("5. Delete\n");
        printf("6. Delete Value\n");
        printf("7. Delete List\n");
        printf("8. Quit\n");
        printf("Enter your choice : ");
        scanf("%d", &choice);
        switch(choice)
        {
        case 1:
