void addend()
{
    struct node* temp;
    temp = (struct node*)malloc(sizeof(struct node));
    printf("Enter Node Data : ");
    scanf("%d", &temp->data);
    printf("%d inserted.\n\n", temp->data);
    temp->link = NULL;

    if(root == NULL)
    {
        root = temp;
    }
    else
    {
        struct node* p;
        p = root;
        while(p->link != NULL)
        {
            p = p->link;
        }
        p->link = temp;
    }
}

void addbegin()
{
    struct node* temp;
    temp = (struct node*)malloc(sizeof(struct node));
    printf("Enter a node to insert : ");
    scanf("%d", &temp->data);
    printf("%d inserted.\n", temp->data);
    temp->link = root;
    root = temp;
}

void addafter()
{
    struct node* temp, * p;
    int key, i = 1;
    printf("Enter location : ");
    scanf("%d", &key);
    len = length();
    if(key > len)
    {
        printf("Unable to insert\n");
        printf("The list is having only %d nodes.\n", len);
    }
    else
    {
        p = root;
        while(i < key)
        {
            p = p->link;
            i++;
        }
        temp = (struct node*)malloc(sizeof(struct node));
        printf("Enter a node to insert : ");
        scanf("%d", &temp->data);
        printf("%d inserted.\n", temp->data);
        temp->link = p->link;
        p->link = temp;
    }
}

void display()
{
    struct node* temp;
    temp = root;
    if(temp == NULL)
    {
        printf("List is Empty\n");
    }
    else
    {
        while(temp != NULL)
        {
            printf("%d-->", temp->data);
            temp = temp->link;
        }
        printf("\n\n");
    }
}

void del()
{
    struct node* temp;
    int key;
    printf("Enter the key : ");
    scanf("%d", &key);
    if(key > length())
    {
        printf("Invalid Location\n");
    }
    else if(key == 1)
    {
        temp = root;
        root = temp->link;
        temp->link = NULL;
        free(temp);
    }
    else
    {
        struct node* p = root, *q;
        int i = 1;
        while(i < key - 1)
        {
            p = p->link;
            i++;
        }
        q = p->link;
        p->link = q->link;
        q->link = NULL;
        free(q);
    }
}

void delval(int value)
{
    struct node* temp, *p = root, *q;
    q = root->link;
    if(root->data == value)
    {
        temp = root;
        root = temp->link;
        temp->link = NULL;
        free(temp);
    }
    else if(search(value) == 1)
    {
        while(q->data != value)
        {
            p = p->link;
            q = p->link;
        }
        p->link = q->link;
        q->link = NULL;
        free(q);
    }
    else
    {
        printf("Value not found in the list.\n\n");
    }
}

void dellist()
{
    struct node *temp = root, *p;
    while(temp != NULL)
    {
        p = temp->link;
        free(temp);
        temp = p;
    }
    printf("All the elements in the list deleted successfully.\n\n");
    root = NULL;
}


int length()
{
    int count = 0;
    struct node* temp;
    temp = root;
    while(temp != NULL)
    {
        count++;
        temp = temp->link;
    }
    printf("The length of the linked list is : %d\n\n", count);
    return count;
}

int search(int value)
{
    struct node *p = root;
    while(p != NULL)
    {
        if(p->data == value)
        {
            return 1;
        }
        else
        {
            p = p->link;
        }
    }
    return 0;
}
