int removeDuplicates(int arr[],int n)
    {
    int i,j=0,*temp,k;
    if(n==0||n==1)
        return n;

    temp=(int *)malloc((n)*sizeof(int *));

    for(i=0;i<n;i++)
        {
        for(j=i+1;j<n;)
            {
            if(arr[i]==arr[j])
                {
                for(k=j;k<n;k++)
                    arr[k]=arr[k+1];
                n--;
                }
            else
                j++;    
            }
        }
    return n;
    }
