      while(cont >= 8){
        lineS[j] = '\t';
        ++j;
        cont = cont - 8;
      }
      for(int l = 0; l < cont; l++){
        lineS[j] = ' ';
        ++j;
      }
    }
    else
      for(int l = 0; l < cont; l++){
        lineS[j] = ' ';
        ++j;
      }
      }
      i = aux;
    }
    else{
      lineS[j] = line[i];
      ++j;
      ++i;
    }
  }
  lineS[j] = '\0';
