int disk[16],d_array[16][16],pos=0;
int ispossible()
{
    int i,ct=0;
    for(i=1;i<16;i++)
    {
        if(disk[i]==0)
            ct++;
    }
    return(ct);
}
void add_file(int id,int size)
{
    int ct=ispossible(),i,j;
    if(ct>=size)
    {
        d_array[pos][0]=id;
        j=1;
        for(i=1;i<16 && size>0;i++)
        {
            if(disk[i]==0)
            {
                disk[i]=id;
                size--;
                d_array[pos][j]=i;
                j++;
            }
        }
        pos++;
    }
    else
    {
        printf("\nNot possible");
    }
}
void rem_file(int id)
{
    int i,j;
    for(i=1;i<16;i++)
    {
        if(disk[i]==id)
        {
            disk[i]=0;
        }
    }
    for(i=0;i<16;i++)
    {
        if(d_array[i][0]==id)
        {
            d_array[i][0]=0;
            for(j=1;j<16;j++)
            {
                if(d_array[i][j]!=0)
                    d_array[i][j]=0;
                else
                    break;
            }
        }
    }
}
