    for(i=1;i<16;i++)
    {
        printf("\t%d",disk[i]);
    }
    printf("\nd_array is : ");
    for(i=0;i<pos;i++)
    {
        if(d_array[i][0]!=0)
        {
            printf("\n%d",d_array[i][0]);
            for(j=1;j<16;j++)   
            {
                if(d_array[i][j]!=0)
                    printf("\t%d",d_array[i][j]);
                else
                    break;
            }
        }
    }
}
