#define F 3
int Queue[F],r=-1,f=-1;
int n,page[100];
int find_pos(int pg,int x)
{
    int i,set=0;
    for(i=x;i<n;i++)
    {
        if(page[i]==pg)
        {
            set=i;
            break;
        }
    }
    return(set);
}
void enqueue(int page,int pos)
{
    int i,new,max=0,set=0;
    if(f==-1 && r==-1)
    {
        f=f+1;
        r=r+1;
        Queue[r]=page;
    }
    else if(r<2)
    {
        r=r+1;
        Queue[r]=page;
    }
    else
    {
        max=0;
        for(i=0;i<3;i++)
        {
            new=find_pos(Queue[i],pos+1);
            if(new>max)
            {
                max=new;
                set=i;
            }
            else if(new==0)
            {
                set=i;
                break;
            }
        }
        Queue[set]=page;
    }
}
int isthere(int page)
{
    int i,flag=-1;
    for(i=0;i<3;i++)
    {
        if(Queue[i]==page)
        {
            flag=1;
