int main()
{
    sigset_t set;
    sigemptyset(&set);
    sigaddset(&set, SIGINT);
    sigaddset(&set, SIGQUIT);
    sigaddset(&set, SIGKILL);   
    sigaddset(&set, SIGBUS);

    sigset_t oldset;
    int ret = sigprocmask(SIG_BLOCK, &set, &oldset);
    if(ret == -1)
        sys_err("sigprocmask error");

    sigset_t pendset;
    while(1)
    {
        ret = sigpending(&pendset);
        if(ret == -1)
            sys_err("sigpending error");

        print_set(&pendset);
        sleep(1);
    }

    return 0;
