    arrecadadoInteiros = ingressosInteirosSobrantes * valorEntradaInteira;
    tolalIngressosVendidos = ingressosInteirosSobrantes + ingressosMeiosSobrantes;
    totalArrecadado = arrecadadoMeios + arrecadadoInteiros;

