typedef struct{
    short int vert;
    short int horiz;
    short int hei;
}offsets;
offsets move[6];


int min=10000;
int n;

int bfs(char*** maze,int*** d,int sr,int sc,int sh){
    rear=-1;front=-1;

    int arrive=0;
    element position;
    position.row = sr;
    position.col = sc;
    position.hei = sh;


    addq(position);
    int i,j,k;
    for(i=0;i<n/2+1;i++){
        for(j=0;j<n+2;j++){
            for(k=0;k<n+2;k++){
                d[i][j][k]=MAX;
            }
        }
    }
    d[sh][sr][sc]=0;


    int nr,nc,nh;
    int row,col,hei;
    while(rear!=front){

        position = deleteq();
        row = position.row;
        col = position.col;
        hei = position.hei;


        if(maze[hei][row][col]=='F'){

            if(min>d[hei][row][col]){
                min = d[hei][row][col];
            }

            arrive=1;
        }

        if(maze[hei][row][col]=='U' || maze[hei][row][col]=='D'){


            int upanddown=-1;
            if(maze[hei][row][col]=='U'){

                upanddown=1;
            }


            nr = row;
            nc = col;
            nh = hei+upanddown;


            if(nh>=0){
                if (maze[nh][nr][nc]!='X' && d[nh][nr][nc]>d[hei][row][col]+1){
                    d[nh][nr][nc]=d[hei][row][col]+1;
                    if(maze[nh][nr][nc]=='T'){
                        d[nh][nr][nc]=d[nh][nr][nc]+2;
                    }
                    element nextposition;
                    nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;
                    addq(nextposition);
                }
            }

        }

        for(i=0;i<4;i++){
            nr = row+move[i].vert;
            nc = col+move[i].horiz;
            nh = hei+move[i].hei;

            if (maze[nh][nr][nc]!='X' && d[nh][nr][nc]>d[hei][row][col]+1){
                d[nh][nr][nc]=d[hei][row][col]+1;
                if(maze[nh][nr][nc]=='T'){
                    d[nh][nr][nc]=d[nh][nr][nc]+2;
                }
                element nextposition;
                nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;
                addq(nextposition);
            }

        }


    }
    return arrive;
}

void path(char*** maze,char*** road,char*** mark,int*** d,int sr,int sc,int sh){
    top=-1;
    top2=-1;
    element position;
    position.row = sr;
    position.col = sc;
    position.hei = sh;
    position.dir = 0 ;
    push(position);


    int i,j,k;
    int nr,nc,nh;
    int row,col,hei,dir;
    int found=1;

    while(top>-1){
        position = pop();


        row = position.row;
        col = position.col;
        hei = position.hei;
        dir = position.dir;



        if(!found){

            while(top2>-1){
                element lastposition = pop2();
                int lr=lastposition.row;int lc=lastposition.col;int lh=lastposition.hei;int ld=lastposition.dir;



                if(lr+move[dir].vert==row && lc+move[dir].horiz==col && lh+move[dir].hei==hei ){
                    push2(lastposition);
                    break;
                }
                road[lh][lr][lc]=maze[lh][lr][lc];
                mark[lh][lr][lc]=maze[lh][lr][lc];
            }
        }
        road[hei][row][col]='*';
        mark[hei][row][col]='X';
        push2(position);
        if(maze[hei][row][col]=='F'){
            break;
        }



        found=0;
        for(i=0;i<4;i++){
            nr = row+move[i].vert;
            nc = col+move[i].horiz;
            nh = hei+move[i].hei;
            if ((mark[nh][nr][nc]!='X' && ((d[nh][nr][nc]==d[hei][row][col]+1)&& mark[nh][nr][nc]!='T') || (d[nh][nr][nc]==d[hei][row][col]+3 && mark[nh][nr][nc]=='T'))){

                found=1;
                element nextposition;
                nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;nextposition.dir=i;
                push(nextposition);
            }
        }
        if(maze[hei][row][col]=='U' || maze[hei][row][col]=='D'){
            int upanddown=-1;
            if(maze[hei][row][col]=='U'){
                upanddown=1;
            }
            nr = row;
            nc = col;
            nh = hei+upanddown;
            if(nh>=0){
                if ((mark[nh][nr][nc]!='X' && ((d[nh][nr][nc]==d[hei][row][col]+1)&& mark[nh][nr][nc]!='T') || (d[nh][nr][nc]==d[hei][row][col]+3 && mark[nh][nr][nc]=='T'))){

                    found=1;
                    element nextposition;
                    nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;
                    if(upanddown==1) nextposition.dir=4;
                    else nextposition.dir=5;
                    push(nextposition);
                }
            }


        }

    }
}

