typedef struct node
{
    int data;
    struct node *left;
    struct node *right;
} node;

node* create()
{
    node *p;

    int x;
    printf("Enter data(-1 for no data):");
    scanf("%d", &x);

    if (x == -1)
        return NULL;

    p = (node*)malloc(sizeof(node));
    p->data = x;

    printf("Enter left child of %d:\n", x);
    p->left = create();

    printf("Enter right child of %d:\n", x);
    p->right = create();

    return p;
}

void inorder(node *t)
{
    if (t == NULL)
        return;

    inorder(t->left);
    printf("%d ", t->data);
    inorder(t->right);
}

node* copy(node *t)
{
    node *p;

    if (t == NULL)
        return NULL;

    p = (node*)malloc(sizeof(node));
    p->data = t->data;

    p->left = copy(t->left);
    p->right = copy(t->right);

    return p;
}

int Equal(node* root1, node* root2)
{
