    }

    printf("Waiting for connection!\n");

    int clientfd = accept(serverfd, (struct sockaddr*)&cliadd, &sockaddr_len);

    printf("Connection established!\n");
    printf("IP: %s\n", inet_ntoa(cliadd.sin_addr));
    printf("Port: %d\n", cliadd.sin_port);

