    temp->llink=temp;
    temp->rlink=temp;
    return temp;
}

void insert(nptr list,int x)
{
    nptr temp=createNode();
    temp->ele=x;
    temp->llink=list;
    temp->rlink=list->rlink;
    list->rlink=temp;
    (temp->rlink)->llink=temp;
