nptr add(nptr num1,nptr num2)
{
    nptr sum=createNode();
    nptr n1=num1->llink,n2=num2->llink;

    int cin=0;
    int s=0;

    while(n1!=num1&&n2!=num2)
    {
        s=n1->ele+n2->ele+cin;

        if(s>=10)
        { 
            cin=1;
            insert(sum, s-10);
        }
        else
        {
            cin=0;
            insert(sum,s);
        }
        n1=n1->llink;
        n2=n2->llink;
    }

    while(n1!=num1)
    {
        s=n1->ele+cin;

        if(s>9)
        { 
            cin=1; 
            insert(sum,s-10);
        }
        else 
        {
            cin=0; 
            insert(sum,s);
        }

        n1=n1->llink;
    }

    while(n2!=num2)
    {
        s=n2->ele+cin;

        if(s>9)
        { 
            cin=1; 
            insert(sum,s-10);
        }
        else 
        {
            cin=0; 
            insert(sum,s);
        }

        n2=n2->llink;
    }

    return sum;
}

