    int dim; 
    printf("inserire dimensione array: "); 
    scanf("%d", &dim);
    int a[dim];


    for(int i=0; i<dim; i++){
        printf("a[%d] = ", i);
        scanf("%d", &a[i]);
    }

    printf("\n");
    printf("----------------------------\n");
    isPrime(dim,a);

  return 0;
